import * as THREE from 'three';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{materials}from'../../core/index.js';import{roundedRect}from'../../core/geometry.js';export{THREE,mesh,FACE,portQuaternion,materials,roundedRect};
export function solid(parent,s,depth,p,m,name){return mesh(parent,new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false,curveSegments:32}),m,p,name);}
export function hole(s,x,y,r){const h=new THREE.Path();h.absarc(x,y,r,0,Math.PI*2,false);s.holes.push(h);}
export function annulus(r,i,d){const s=new THREE.Shape();s.absarc(0,0,r,0,Math.PI*2,false);hole(s,0,0,i);return new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:32});}
/** Closed tapered flex ribbon,profiled about a YZ path. No animated bend or assembly joint. */
export function ribbon(parent,sections,material,name){const p=[],ix=[];for(let k=0;k<sections.length;k++){const s=sections[k],prev=sections[Math.max(0,k-1)],next=sections[Math.min(sections.length-1,k+1)],dy=next.y-prev.y,dz=next.z-prev.z,l=Math.hypot(dy,dz),ny=-dz/l,nz=dy/l,t=(s.thickness??.1)/2,c=s.x??0;for(const[x,sign]of[[-s.width/2,-1],[s.width/2,-1],[s.width/2,1],[-s.width/2,1]])p.push(c+x,s.y+ny*t*sign,s.z+nz*t*sign);}for(let k=0;k<sections.length-1;k++)for(let i=0;i<4;i++){const j=(i+1)%4,a=k*4+i,b=k*4+j,c=(k+1)*4+j,d=(k+1)*4+i;ix.push(a,b,c,a,c,d);}ix.push(0,2,1,0,3,2);const e=(sections.length-1)*4;ix.push(e,e+1,e+2,e,e+2,e+3);let volume=0;for(let k=0;k<ix.length;k+=3){const a=new THREE.Vector3().fromArray(p,ix[k]*3),b=new THREE.Vector3().fromArray(p,ix[k+1]*3),c=new THREE.Vector3().fromArray(p,ix[k+2]*3);volume+=a.dot(b.cross(c));}if(volume<0)for(let k=0;k<ix.length;k+=3)[ix[k+1],ix[k+2]]=[ix[k+2],ix[k+1]];const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(p,3));g.setIndex(ix);g.computeVertexNormals();return mesh(parent,g,material,[0,0,0],name);}
